import { Resend } from "resend";
const emailPattern=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function clean(value:unknown,max:number){return typeof value==="string"?value.trim().slice(0,max):""}
export async function POST(request:Request){try{const body=await request.json();const name=clean(body.name,100),email=clean(body.email,200),company=clean(body.company,120),service=clean(body.service,120),message=clean(body.message,5000),website=clean(body.website,200);if(website)return Response.json({ok:true});if(!name||!email||!message||!emailPattern.test(email))return Response.json({error:"Please provide a valid name, email, and project description."},{status:400});if(message.length<20)return Response.json({error:"Please provide a little more detail about the project."},{status:400});if(!process.env.RESEND_API_KEY||!process.env.RESEND_FROM_EMAIL||!process.env.CONTACT_TO_EMAIL)return Response.json({error:"Contact delivery is not configured yet. Please configure the Resend environment variables."},{status:503});const resend=new Resend(process.env.RESEND_API_KEY);const result=await resend.emails.send({from:process.env.RESEND_FROM_EMAIL,to:[process.env.CONTACT_TO_EMAIL],replyTo:email,subject:`SnowSeasonsTech project inquiry${company?` — ${company}`:""}`,text:[`Name: ${name}`,`Email: ${email}`,`Company: ${company||"Not provided"}`,`Service: ${service||"Not specified"}`,"",message].join("\n")});if(result.error)return Response.json({error:"The message could not be delivered. Please try again."},{status:502});return Response.json({ok:true})}catch{return Response.json({error:"Invalid request. Please try again."},{status:400})}}
